def site(id,name,developer,customer,place,state,lat,lon,mw,basis,window,first,last,status,power,stage,refs,**kw):
    rows.append(dict(id=id,name=name,developer=developer,customer=customer,place=place,state=state,lat=lat,lon=lon,mw=mw,basis=basis,readyWindow=window,firstYear=first,lastYear=last,status=status,power=power,stage=stage,sources=refs,confirmedSupplyMw=None,supplyMeaning='Site-specific supply MW not quantified in reviewed material',gridWindow='Customer-load connection date not verified',gas='Firm gas delivery not verified',permit='Primary turbine permit not matched',fit='Not qualified for Mod-1',modelEligible=False,phase2027=0,phase2028=0,bridgeFraction=0,deductMw=0,**{}))
    rows[-1].update(kw)

