# Keep 50 main records; preserve four secondary/out-of-horizon leads in a separate audit.
supplemental=[r for r in rows if r['id'] in ['hawkeye','chesapeake','reveille','meta_prometheus']]
rows=[r for r in rows if r not in supplemental]
for r in rows:
    for key in ['firstYear','lastYear']:
        if isinstance(r[key],str):r[key]=int(r[key])
    r['coordinateBasis']='Approximate city / regional marker; not a surveyed facility footprint' if r['lat'] is not None else 'Undisclosed location; omitted from map'
    r['reviewed']='2026-10-06'
    r['durationMonths']=None
    r['verifiedOpenMw']=None
    if r['state']=='TX':r['regulatoryNote']='September 21 TCEQ pause: site-specific permit status and audit completion must be checked.'
    else:r['regulatoryNote']='No generic permission assumed; emissions, fuel and customer acceptance are site-specific.'
used={sid for r in rows for sid in r['sources']}|{'dc_tx_pause','dc_ercot_rfi','gev_capacity','siemens_slots','wartsila_slots','wartsila_282','volta_oracle','gev_crusoe_units','ftai_q2'}
missing=used-sources.keys()
assert not missing,missing
out=dict(asOf='2026-10-06',scope='50 US named-campus and campus-program records, including an operating turbine control. Purposive coverage of major hyperscalers and AI developers; not an exhaustive global registry or a statistical meta-analysis.',rows=rows,supplemental=supplemental,sources=[sources[id] for id in sorted(used)],defaults=dict(year=2028,pue=1.2,competitorShare=.5,capture=.25,phaseScale=1,includeTiming=True,derate=.1,reserve=.1,annualUnits=100),limitations=['Announcements and utility contracts are guidance, not commissioned load.','Only IT and explicitly electrical capacity enter normalized demand; generation and unspecified MW stay separate.','Modeling undisclosed supplier allocation as a potential procurement pool does not prove an open tender.','No independent execution-qualified open MW or shortage duration established.','Default 2028 phase and bridge fractions are team assumptions and editable; a service-ready date is not assigned to unknown cases.'],previous=dict(openMw=564.1,sites=2,scope='2027 two-site model; 50% load phase and 50% remaining competing supply. Different cohort, basis and horizon from this census.'))
(R/'data/datacenter_study.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
print(f'Curated {len(rows)} campus/program records and {len(out["sources"])} sources.')
